import heapq
cost = lambda r, c: (r * c) % 5 + 1
dist, pq = {}, [(0, 0, 0)]
while pq:
    d, r, c = heapq.heappop(pq)
    if (r, c) in dist: continue
    dist[(r, c)] = d
    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
        if 0 <= nr < 5 and 0 <= nc < 5 and (nr, nc) not in dist: heapq.heappush(pq, (d + cost(nr, nc), nr, nc))
result = dist[(4, 4)]
